package com.grifplot.libros;
import java.io.*;import java.net.*;import java.util.*;import java.util.regex.*;
final class ImageOriginals {
 static String clean(String s){return s.replace("&amp;","&").replace("&quot;","\"").replace("&#39;","'").replace("\\/","/");}
 static String attr(String tag,String name){Matcher m=Pattern.compile("(?i)(?:^|\\s)"+Pattern.quote(name)+"\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))").matcher(tag);return m.find()?clean(m.group(1)!=null?m.group(1):m.group(2)!=null?m.group(2):m.group(3)):"";}
 static boolean same(String a,String b){String x=SearchCore.norm(a),y=SearchCore.norm(b);if(x.length()<8||y.length()<8)return false;Set<String> xs=new HashSet<>(Arrays.asList(x.split(" "))),ys=new HashSet<>(Arrays.asList(y.split(" ")));int n=0;for(String w:xs)if(w.length()>2&&ys.contains(w))n++;return n>=2&&(x.contains(y)||y.contains(x)||n>=Math.max(xs.size(),ys.size())*.75);}
 static void add(Set<String> out,String base,String value){if(value.isEmpty()||out.size()>=8)return;try{URL u=new URL(new URL(base),clean(value));if(u.getProtocol().equals("https")&&!ImagePack.googlePreview(u.toString()))out.add(u.toString());}catch(Exception ignored){}}
 static List<String> candidates(String html,String source,String title,String known){LinkedHashSet<String> result=new LinkedHashSet<>();Matcher m=Pattern.compile("(?is)<img\\b[^>]*>").matcher(html);while(m.find()){String tag=m.group(),src=attr(tag,"src");if(!same(title,attr(tag,"alt"))&&(known.isEmpty()||!known.equals(src)))continue;int before=result.size();for(String a:new String[]{"data-original","data-full","data-zoom-image","data-large-file"})add(result,source,attr(tag,a));String best="";double max=0;for(String v:attr(tag,"srcset").split(",")){String[] p=v.trim().split("\\s+");if(p.length>1)try{double width=Double.parseDouble(p[1].replaceAll("[wx]$",""))*(p[1].endsWith("x")?1000:1);if(width>max){max=width;best=p[0];}}catch(Exception ignored){}}add(result,source,best);if(result.size()==before){add(result,source,attr(tag,"data-src"));add(result,source,src);}}
 Matcher obj=Pattern.compile("(?is)\\{[^{}]{0,24000}\"@type\"\\s*:\\s*\"ImageObject\"[^{}]{0,24000}\\}").matcher(html);while(obj.find()){String v=obj.group();Matcher n=Pattern.compile("\"(?:name|caption)\"\\s*:\\s*\"([^\"]+)\"").matcher(v),u=Pattern.compile("\"contentUrl\"\\s*:\\s*\"([^\"]+)\"").matcher(v);if(n.find()&&same(title,clean(n.group(1)))&&u.find())add(result,source,u.group(1));}return new ArrayList<>(result);}
 static List<String> resolve(ImagePack.Item item,String ua,ImagePack.Progress p){if(item.source.isEmpty()||item.source.contains("google.com/")||ImagePack.googlePreview(item.source))return Collections.emptyList();HttpURLConnection c=null;try{URL address=ImagePack.publicUrl(item.source);for(int i=0;i<4;i++){if(p.cancelled())return Collections.emptyList();c=(HttpURLConnection)address.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(7000);c.setRequestProperty("User-Agent",ua);int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)break;address=ImagePack.publicUrl(new URL(address,location).toString());c.disconnect();c=null;continue;}if(status!=200)break;String type=c.getContentType();if(type!=null&&type.toLowerCase(Locale.ROOT).startsWith("image/"))return Collections.singletonList(address.toString());if(type!=null&&!type.toLowerCase(Locale.ROOT).contains("html"))break;try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(p.cancelled()||bytes.size()+n>2097152)return Collections.emptyList();bytes.write(buf,0,n);}return candidates(new String(bytes.toByteArray(),"UTF-8"),address.toString(),item.title,item.url);}}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}return Collections.emptyList();}
}
